(function(){
  var $input = $('input[name=\'filter_customer\']');

  function ocxGetUrlParam(name){
    var s = window.location.search || '';
    if (!s) return '';
    s = s.replace(/^\?/, '');
    var parts = s.split('&');
    for (var i=0;i<parts.length;i++){
      var kv = parts[i].split('=');
      if (decodeURIComponent(kv[0] || '') === name) return decodeURIComponent(kv[1] || '');
    }
    return '';
  }
  function ocxHtmlDecode(str){ return $('<textarea/>').html(str || '').text(); }
  function ocxEscapeHtml(s){ return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;'); }
  function ocxDigitsOnly(s){ return String(s || '').replace(/\D+/g,''); }
  function ocxLast10Digits(s){ var d = ocxDigitsOnly(s); if (d.length > 10) d = d.slice(-10); return d; }
  function ocxHighlightText(text, term){
    text = String(text || '');
    term = String(term || '');
    if (!term) return ocxEscapeHtml(text);
    var safe = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var re = new RegExp('(' + safe + ')', 'ig');
    return ocxEscapeHtml(text).replace(re, '<u>$1</u>');
  }
  function ocxUnderlineDigitsInFormatted(formatted, needleDigits){
    formatted = String(formatted || '');
    needleDigits = String(needleDigits || '');
    if (!needleDigits) return ocxEscapeHtml(formatted);
    var digits = [];
    var pos = [];
    for (var i=0;i<formatted.length;i++){
      var ch = formatted.charAt(i);
      if (ch >= '0' && ch <= '9'){ digits.push(ch); pos.push(i); }
    }
    var hay = digits.join('');
    var idx = hay.indexOf(needleDigits);
    if (idx === -1) return ocxEscapeHtml(formatted);
    var startPos = pos[idx];
    var endPos = pos[idx + needleDigits.length - 1] + 1;
    return ocxEscapeHtml(formatted.slice(0, startPos)) + '<u>' + ocxEscapeHtml(formatted.slice(startPos, endPos)) + '</u>' + ocxEscapeHtml(formatted.slice(endPos));
  }
  function ocxGetMode(){ var $r = $('input[name="ocx_customer_mode"]:checked'); return $r.length ? $r.val() : 'name'; }
  function ocxSetMode(mode){ $('input[name="ocx_customer_mode"][value="'+mode+'"]').prop('checked', true); }
  function ocxSetPlaceholder(){
    var mode = ocxGetMode();
    var ph = '{{ entry_customer }}';
    if (mode === 'telephone') ph = 'Телефон покупателя';
    else if (mode === 'email') ph = 'Email покупателя';
    else if (mode === 'inn') ph = 'ИНН';
    else if (mode === 'business') ph = 'Название бизнеса';
    else if (mode === 'legal') ph = 'Юр.лицо / строка';
    $input.attr('placeholder', ph);
  }

  var urlMode = ocxGetUrlParam('ocx_mode');
  var storedMode = '';
  try { storedMode = localStorage.getItem('ocx_customer_mode') || ''; } catch(e){}
  ocxSetMode(urlMode || storedMode || 'name');
  ocxSetPlaceholder();

  $(document).on('change', 'input[name="ocx_customer_mode"]', function(){
    var m = ocxGetMode();
    try { localStorage.setItem('ocx_customer_mode', m); } catch(e){}
    ocxSetPlaceholder();
    $input.trigger('focus').trigger('keyup');
  });

  $(function(){
    $('#button-filter').off('click').on('click', function(){
      var mode = ocxGetMode();
      function go(){
        var url = '';
        var filter_order_id = $('input[name=\'filter_order_id\']').val(); if (filter_order_id) url += '&filter_order_id=' + encodeURIComponent(filter_order_id);
        var filter_customer = $('input[name=\'filter_customer\']').val(); if (filter_customer) url += '&filter_customer=' + encodeURIComponent(filter_customer);
        var filter_order_status_id = $('select[name=\'filter_order_status_id\']').val(); if (filter_order_status_id !== '') url += '&filter_order_status_id=' + encodeURIComponent(filter_order_status_id);
        var filter_total = $('input[name=\'filter_total\']').val(); if (filter_total) url += '&filter_total=' + encodeURIComponent(filter_total);
        var filter_date_added = $('input[name=\'filter_date_added\']').val(); if (filter_date_added) url += '&filter_date_added=' + encodeURIComponent(filter_date_added);
        var filter_date_modified = $('input[name=\'filter_date_modified\']').val(); if (filter_date_modified) url += '&filter_date_modified=' + encodeURIComponent(filter_date_modified);
        if (mode) url += '&ocx_mode=' + encodeURIComponent(mode);
        location = 'index.php?route=sale/order&user_token={{ user_token }}' + url;
      }

      var q = $.trim($input.val() || '');
      if (mode !== 'name' && q) {
        $.ajax({
          url: 'index.php?route=customer/customer/autocomplete&user_token={{ user_token }}&ocx_mode=' + encodeURIComponent(mode) + '&filter_name=' + encodeURIComponent(q),
          dataType: 'json',
          success: function(json){ if (json && json.length) { var nm = ocxHtmlDecode(json[0]['name_plain'] || json[0]['name'] || ''); if (nm) $input.val(nm); } go(); },
          error: function(){ go(); }
        });
      } else {
        go();
      }
    });
  });

  window.ocxCustomerFilter = { getMode: ocxGetMode, htmlDecode: ocxHtmlDecode, escape: ocxEscapeHtml, digits: ocxDigitsOnly, last10: ocxLast10Digits, hiText: ocxHighlightText, hiPhone: ocxUnderlineDigitsInFormatted };
})();

var ocx_mode = window.ocxCustomerFilter.getMode();
var ocx_q = String(request || '').trim();
if (ocx_mode === 'name' && !ocx_q) { response([]); return; }

var ocx_mode = window.ocxCustomerFilter.getMode();
var ocx_term = String(request || '');
var ocx_term10 = window.ocxCustomerFilter.last10(ocx_term);

