$ocx_mode = 'name';
if (isset($this->request->get['ocx_mode']) && $this->request->get['ocx_mode']) {
  $ocx_mode = $this->request->get['ocx_mode'];
}

$ocx_source = '';
if (isset($this->request->get['filter_name'])) {
  $ocx_source = $this->request->get['filter_name'];
} elseif (isset($this->request->get['filter_customer'])) {
  $ocx_source = $this->request->get['filter_customer'];
}

$ocx_raw = html_entity_decode((string)$ocx_source, ENT_QUOTES, 'UTF-8');

$ocx_phone10 = '';
if ($ocx_mode == 'telephone') {
  $ocx_digits = preg_replace('/\D+/', '', $ocx_raw);
  if (strlen($ocx_digits) > 10) {
    $ocx_phone10 = substr($ocx_digits, -10);
  } else {
    $ocx_phone10 = $ocx_digits;
  }
}

$ocx_json = '';
$ocx_json_enc = json_encode($ocx_raw);
if ($ocx_json_enc !== false && strlen($ocx_json_enc) >= 2) {
  $ocx_json = substr($ocx_json_enc, 1, -1);
}

$ocx_cf_inn = '';
