  }
}

$result['ocx_cf_inn'] = $ocx_cf_inn;
$result['ocx_cf_business'] = $ocx_cf_business;
$result['ocx_cf_legal'] = $ocx_cf_legal;

if (isset($data['filter_ocx_mode']) && $data['filter_ocx_mode'] && $data['filter_ocx_mode'] != 'name') {
  $ocx_mode = $data['filter_ocx_mode'];
  $ocx_raw  = isset($data['filter_ocx_raw']) ? $data['filter_ocx_raw'] : '';
  $ocx_json = isset($data['filter_ocx_json']) ? $data['filter_ocx_json'] : '';
  $ocx_phone = isset($data['filter_ocx_phone']) ? $data['filter_ocx_phone'] : '';

  if ($ocx_mode == 'telephone') {
    $clean = "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(c.telephone,'+',''),' ',''),'-',''),'(',''),')',''),'.',''),'/',''),',',''),';','')";
    if ($ocx_phone !== '') {
      if (strlen($ocx_phone) >= 10) {
        $sql .= " AND RIGHT(" . $clean . ", 10) LIKE '%" . $this->db->escape($ocx_phone) . "%'";
      } else {
        $sql .= " AND (" . $clean . " LIKE '%" . $this->db->escape($ocx_phone) . "%' OR RIGHT(" . $clean . ", 10) LIKE '%" . $this->db->escape($ocx_phone) . "%')";
      }
    }
  } elseif ($ocx_mode == 'email' && $ocx_raw !== '') {
    $sql .= " AND LCASE(c.email) LIKE '%" . $this->db->escape(utf8_strtolower($ocx_raw)) . "%'";
  } elseif (($ocx_mode == 'inn' || $ocx_mode == 'business' || $ocx_mode == 'legal') && $ocx_raw !== '') {
    $key = ($ocx_mode == 'inn') ? '3' : (($ocx_mode == 'business') ? '5' : '9');
    if ($ocx_mode == 'inn') {
      $ocx_raw = preg_replace('/\D+/', '', $ocx_raw);
      $ocx_json = $ocx_raw;
    }

    $field_expr = "JSON_UNQUOTE(JSON_EXTRACT(c.custom_field, '$." . $this->db->escape($key) . "'))";
    $sql .= " AND (LCASE(" . $field_expr . ") LIKE '%" . $this->db->escape(utf8_strtolower($ocx_raw)) . "%'";

    $like_raw = "%\\\"" . $this->db->escape($key) . "\\\":\\\"%" . $this->db->escape($ocx_raw) . "%";
    $sql .= " OR c.custom_field LIKE '" . $like_raw . "'";

    if ($ocx_json !== '' && $ocx_json !== $ocx_raw) {
      $like_json = "%\\\"" . $this->db->escape($key) . "\\\":\\\"%" . $this->db->escape($ocx_json) . "%";
      $sql .= " OR c.custom_field LIKE '" . $like_json . "'";
    }

    $sql .= ")";
  } else {
    $parts = explode(' ', trim($ocx_raw));
    $implode = array();
    foreach ($parts as $part) {
      if ($part) {
        $implode[] = "LCASE(CONCAT(c.firstname, ' ', c.lastname)) LIKE '%" . $this->db->escape(utf8_strtolower($part)) . "%'";
      }
    }
    if ($implode) {
      $sql .= " AND (" . implode(" AND ", $implode) . ")";
    }
  }

